if(typeof Block2_1Slider==='undefined'){function Block2_1Slider(blockId){this.$slider=$('#block_'+blockId).find('.tizers');this.options={arrows:false,dots:true,cssEase:'linear',slidesToShow:1};this.isInitProcess=false;this.isDestroyProcess=false;this.subscribeToEvents();this.resizeHandler()}Block2_1Slider.prototype.dotsHandler=function(e,slick){slick.$slider.find('.slick-dots li').each(function(){$(this).addClass('theme-bg')});if(slick.$slider.find('.slick-track').children().length===1){slick.$slider.addClass('slider--one-slide')}};Block2_1Slider.prototype.lazyLoadHandler=function(e,slick){if(typeof lazyLoadInstance!=='undefined'){lazyLoadInstance.update()}};Block2_1Slider.prototype.isMobile=function(){return window.matchMedia('(max-width: 767px)').matches};Block2_1Slider.prototype.isInit=function(){return this.$slider.hasClass('slick-initialized')};Block2_1Slider.prototype.isProcess=function(){return this.isInitProcess||this.isDestroyProcess};Block2_1Slider.prototype.resizeHandler=function(){if(this.isProcess()){return}if(this.isMobile()&&!this.isInit()){this.isInitProcess=true;this.$slider.slick(this.options);return}if(!this.isMobile()&&this.isInit()){this.isDestroyProcess=true;this.$slider.slick('unslick')}};Block2_1Slider.prototype.initHandler=function(slick){this.isInitProcess=false};Block2_1Slider.prototype.destroyHandler=function(event,slick){this.isDestroyProcess=false};Block2_1Slider.prototype.subscribeToEvents=function(){this.$slider.on('init reInit afterChange',this.lazyLoadHandler);this.$slider.on('init reInit',this.dotsHandler.bind(this));this.$slider.on('init reInit',this.initHandler.bind(this));this.$slider.on('destroy',this.destroyHandler.bind(this));$(window).on('resize',this.resizeHandler.bind(this))};Block2_1Slider.prototype.release=function(){this.$slider.off('init reInit afterChange',this.lazyLoadHandler);this.$slider.off('init reInit',this.dotsHandler.bind(this));this.$slider.off('init reInit',this.initHandler.bind(this));this.$slider.off('destroy',this.destroyHandler.bind(this));$(window).off('resize',this.resizeHandler.bind(this))}}